/* 
 * STM32_Node_Code.c
 * Application code for STM32 Motor Controller Node
 * Note: This contains the core application logic. In a real project, this would be 
 * integrated into the main.c generated by STM32CubeMX (which handles clock/peripheral init).
 */

#include "main.h"
#include "cmsis_os.h" // FreeRTOS header
#include <string.h>

// --- System & Protocol Definitions ---
#define CAN_ID_SETPOINT  0x100
#define CAN_ID_TELEMETRY 0x101
#define CAN_ID_HEARTBEAT 0x102

#define TIMEOUT_MS 2000 // 2 seconds timeout for failsafe connection

// --- Motor & PID Variables ---
float Kp = 1.5, Ki = 0.5, Kd = 0.05;
float error = 0, prev_error = 0, integral = 0, derivative = 0;
float target_rpm = 0.0;
float current_rpm = 0.0;
int16_t pwm_output = 0;

// --- System State Variables ---
uint32_t last_heartbeat_time = 0;

// --- Peripheral Handles (Assume generated by CubeMX) ---
extern CAN_HandleTypeDef hcan1;
extern TIM_HandleTypeDef htim2;  // Hardware Encoder Timer
extern TIM_HandleTypeDef htim3;  // Hardware PWM Timer
extern IWDG_HandleTypeDef hiwdg; // Independent Watchdog

// --- FreeRTOS Task Prototypes ---
void TaskMotorControl(void *argument);
void TaskCAN_Comm(void *argument);
void TaskHeartbeat(void *argument);

int main(void) {
    // HAL_Init(), SystemClock_Config(), MX_GPIO_Init(), etc. (Generated by CubeMX)
    
    // 1. Start Hardware Timers
    HAL_TIM_Encoder_Start(&htim2, TIM_CHANNEL_ALL);
    HAL_TIM_PWM_Start(&htim3, TIM_CHANNEL_1); // Motor Forward PWM
    HAL_TIM_PWM_Start(&htim3, TIM_CHANNEL_2); // Motor Reverse PWM

    // 2. Start CAN Bus & Enable RX Interrupts
    HAL_CAN_Start(&hcan1);
    HAL_CAN_ActivateNotification(&hcan1, CAN_IT_RX_FIFO0_MSG_PENDING);

    // 3. Create FreeRTOS Tasks
    // Motor control needs highest priority (Realtime) to guarantee 10ms loop
    xTaskCreate(TaskMotorControl, "MotorTask", 256, NULL, osPriorityRealtime, NULL);
    // CAN Comm handles telemetry (Normal priority)
    xTaskCreate(TaskCAN_Comm, "CANTask", 256, NULL, osPriorityNormal, NULL);
    // Heartbeat & Watchdog (Low priority)
    xTaskCreate(TaskHeartbeat, "HeartbeatTask", 128, NULL, osPriorityLow, NULL);

    last_heartbeat_time = HAL_GetTick();

    // 4. Start RTOS Scheduler
    vTaskStartScheduler();
    
    // Should never reach here
    while (1) {}
}

/* 
 * TASK 1: Motor Control & PID (100Hz Loop)
 * Handles encoder reading, PID calculation, and PWM output.
 */
void TaskMotorControl(void *argument) {
    const TickType_t xFrequency = pdMS_TO_TICKS(10); // 10ms loop (100Hz)
    TickType_t xLastWakeTime = xTaskGetTickCount();
    
    int32_t prev_encoder_count = 0;

    for(;;) {
        // --- 1. System Failsafe ---
        // If ESP32 stops sending heartbeats, safely stop the motor
        if ((HAL_GetTick() - last_heartbeat_time) > TIMEOUT_MS) {
            target_rpm = 0.0; 
        }

        // --- 2. Read Encoder & Compute RPM ---
        int32_t encoder_count = __HAL_TIM_GET_COUNTER(&htim2);
        int32_t delta = encoder_count - prev_encoder_count;
        prev_encoder_count = encoder_count;
        
        // Handle 16-bit timer overflow/underflow
        if (delta > 32768) delta -= 65536;
        else if (delta < -32768) delta += 65536;

        // Calculate RPM (Assuming 1200 Counts Per Rev, and 10ms loop time)
        current_rpm = ((float)delta * 6000.0f) / 1200.0f; 

        // --- 3. PID Math ---
        error = target_rpm - current_rpm;
        integral += error * 0.01f; // dt = 10ms (0.01s)
        
        // Anti-windup clamping for integral
        if(integral > 500) integral = 500;
        if(integral < -500) integral = -500;

        derivative = (error - prev_error) / 0.01f;
        prev_error = error;

        float control_signal = (Kp * error) + (Ki * integral) + (Kd * derivative);
        
        // Clamp output to Timer Period (e.g., 1000 max PWM)
        if(control_signal > 1000) control_signal = 1000;
        if(control_signal < -1000) control_signal = -1000;
        pwm_output = (int16_t)control_signal;

        // --- 4. Apply PWM to Motor Driver (TB6612/DRV8833) ---
        if (pwm_output > 0) {
            __HAL_TIM_SET_COMPARE(&htim3, TIM_CHANNEL_1, pwm_output);
            __HAL_TIM_SET_COMPARE(&htim3, TIM_CHANNEL_2, 0);
        } else {
            __HAL_TIM_SET_COMPARE(&htim3, TIM_CHANNEL_1, 0);
            __HAL_TIM_SET_COMPARE(&htim3, TIM_CHANNEL_2, -pwm_output); // Positive magnitude
        }

        // Wait precisely 10ms
        vTaskDelayUntil(&xLastWakeTime, xFrequency);
    }
}

/* 
 * TASK 2: CAN Communication Tx (10Hz Loop)
 * Transmits telemetry data over the CAN bus to the ESP32.
 */
void TaskCAN_Comm(void *argument) {
    CAN_TxHeaderTypeDef TxHeader;
    uint32_t TxMailbox;
    uint8_t TxData[8];

    TxHeader.StdId = CAN_ID_TELEMETRY;
    TxHeader.ExtId = 0x01;
    TxHeader.RTR = CAN_RTR_DATA;
    TxHeader.IDE = CAN_ID_STD;
    TxHeader.DLC = 8;

    for(;;) {
        // Package 2 floats into 8 bytes
        memcpy(TxData, &current_rpm, 4);
        memcpy(TxData+4, &target_rpm, 4);
        
        // Send if mailbox is free
        if (HAL_CAN_GetTxMailboxesFreeLevel(&hcan1) > 0) {
            HAL_CAN_AddTxMessage(&hcan1, &TxHeader, TxData, &TxMailbox);
        }
        
        vTaskDelay(pdMS_TO_TICKS(100)); // 100ms delay (10Hz)
    }
}

/* 
 * CAN RX Interrupt Callback 
 * Fires immediately when a message arrives on the bus.
 */
void HAL_CAN_RxFifo0MsgPendingCallback(CAN_HandleTypeDef *hcan) {
    CAN_RxHeaderTypeDef RxHeader;
    uint8_t RxData[8];
    
    if (HAL_CAN_GetRxMessage(hcan, CAN_RX_FIFO0, &RxHeader, RxData) == HAL_OK) {
        if (RxHeader.StdId == CAN_ID_SETPOINT) {
            // New speed command received
            memcpy(&target_rpm, RxData, 4); 
        } else if (RxHeader.StdId == CAN_ID_HEARTBEAT) {
            // Heartbeat received from ESP32, reset failsafe timer
            last_heartbeat_time = HAL_GetTick(); 
        }
    }
}

/* 
 * TASK 3: System Heartbeat & Watchdog (2Hz Loop)
 */
void TaskHeartbeat(void *argument) {
    for(;;) {
        HAL_GPIO_TogglePin(GPIOA, GPIO_PIN_5); // Toggle Status LED
        HAL_IWDG_Refresh(&hiwdg);              // Pet the Watchdog Timer
        vTaskDelay(pdMS_TO_TICKS(500));
    }
}
